-- Seed 03: groups, recurring series, calendar events, staff availability
-- DEV/STAGE TEST DATA ONLY. Conventions: see R__seed_01_identity.sql.
--
-- Event times are relative to the week the seed first ran (week -1 = past, +1/+2 = upcoming),
-- so a fresh database always has a past and an upcoming schedule.
--
-- Events (19...NN):
--   01 Pole beginners  Tue w-1 18:00  COMPLETED       07 Personal training Marek/Tomasz  Wed w-1 17:00  COMPLETED
--   02 Pole beginners  Tue w+1 18:00  (substitution)  08 Personal training Ewa/Katarzyna Wed w+1 17:00
--   03 Pole beginners  Thu w+1 18:00  capacity 2      09 Stretching workshop            Sat w+2 12:00
--   04 Pole beginners  Tue w+2 18:00  CANCELLED       10 Consultation with a guest      Fri w+1 16:00
--   05 Calisthenics    Mon w+1 19:00                  11 Room block (maintenance)       Fri w+1 08:00
--   06 Pole kids       Sat w+1 10:00                  12 Pole beginners                 Thu w+2 18:00

-- Studio-local time in a week relative to the current one, for an ISO weekday (1 = Monday).
CREATE OR REPLACE FUNCTION pg_temp.seed_at(week_offset INT, iso_weekday INT, local_time TIME)
RETURNS TIMESTAMPTZ LANGUAGE sql AS $$
    SELECT (date_trunc('week', now() AT TIME ZONE 'Europe/Warsaw')
            + make_interval(weeks => week_offset, days => iso_weekday - 1)
            + (local_time - TIME '00:00')) AT TIME ZONE 'Europe/Warsaw'
$$;

